from jsonb_to_recordset($json$[{"id":"che-pe-251","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Lithium shows a diagonal resemblance in several of its compounds to","options":["sodium","magnesium","potassium","fluorine"],"answer_index":1,"explanation":"Li and Mg have similar charge-to-radius ratios, so their oxides, fluorides and carbonates behave alike.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"metallic-character","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-252","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Silicon is classified as a metalloid, sitting on the diagonal staircase of the","options":["s-block","p-block","f-block","noble-gas column"],"answer_index":1,"explanation":"Si lies between the metal Al and the non-metal P and shows intermediate electrical and chemical behaviour.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"metallic-character","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-253","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Caesium is more metallic than lithium because the valence electron of Cs is","options":["closer to the nucleus and harder to lose","farther from the nucleus and more easily lost","a 2s electron","part of a filled p⁶ set"],"answer_index":1,"explanation":"The 6s electron of Cs is highly shielded, so Cs has a very low IE and extreme metallic character.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"metallic-character","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-254","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Aluminium is distinctly more metallic than boron, even though both head group 13, because Al is","options":["smaller and has a higher ionisation enthalpy","larger and has a much lower ionisation enthalpy","a noble gas","an f-block element"],"answer_index":1,"explanation":"Two trends reinforce: down the group size rises and IE falls, turning the head (B, a non-metal/metalloid) into a metal (Al).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"metallic-character","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-255","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The first element of a p-block or s-block group differs markedly from the","options":["noble gases only","heavier members of that group","isotopes of hydrogen","inner transition metals alone"],"answer_index":1,"explanation":"Li, Be, B, C, N, O and F are the classic anomalous first members.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"anomalous-first","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-256","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The anomalous behaviour of the first element is largely due to its","options":["large size and low electronegativity","small size and high electronegativity","empty 4f subshell","very low ionisation enthalpy"],"answer_index":1,"explanation":"A compact valence shell and high χ (and IE) set the head element apart from its congeners.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"anomalous-first","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-257","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Second-period elements lack vacant d orbitals, so they cannot","options":["form any covalent bond","expand their octet the way heavier congeners can","show a +1 oxidation state","exist as isolated atoms"],"answer_index":1,"explanation":"N, O and F are limited to an octet; P, S and Cl can use 3d orbitals in PF₅, SF₆, ClF₃, and so on.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"anomalous-first","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-258","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Lithium differs from the rest of the alkali metals in several properties, including the low solubility of its","options":["chloride only","fluoride and carbonate","all nitrates","hydride vapour"],"answer_index":1,"explanation":"LiF and Li₂CO₃ resemble the corresponding magnesium salts more than those of Na or K.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"anomalous-first","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-259","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Lithium shows a diagonal relationship with","options":["sodium","magnesium","caesium","fluorine"],"answer_index":1,"explanation":"The Li–Mg pair is the textbook diagonal relationship of group 1 / group 2.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"anomalous-first","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-260","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Beryllium and aluminium form a well-known","options":["inert-pair pair","diagonal pair","isotope pair","noble-gas pair"],"answer_index":1,"explanation":"Be and Al share amphoteric oxides, covalent chlorides and a similar charge-to-radius ratio.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"anomalous-first","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
